const terrainNames={plain:'Sungrass plains',forest:'Elderwood',hill:'Kingsfall hills',water:'Flooded pass',mountain:'High peaks',ruins:'Old-world ruins'};
const techs=[
 {id:'war',name:'Forged in Battle',icon:'⚔',description:'All your armies gain +1 power in battle.',cost:15,arcana:7,max:3},
 {id:'lore',name:'The Old Tongue',icon:'✧',description:'Gain +2 arcana at the start of each year.',cost:13,arcana:6,max:3},
 {id:'land',name:'Granary & Guild',icon:'⌂',description:'Gain +3 gold and +2 food at the start of each year.',cost:16,arcana:6,max:3}
];
let game=null;let toastTimer;
const $=s=>document.querySelector(s);
function makeMap(){return terrainMap.flatMap((row,y)=>row.map((terrain,x)=>({id:`${x}-${y}`,x,y,terrain,owner:null,units:0,veteran:0,capital:false,seen:false})));}
function startGame(key){const n=nations[key];game={nation:key,turn:1,ap:2,gold:38,food:24,arcana:12,selected:'0-2',tiles:makeMap(),tech:{war:0,lore:0,land:0},log:[],events:[],finished:false};const own=tile(0,2);own.owner='you';own.capital=true;own.units=4;own.seen=true;tile(0,1).owner='you';tile(0,1).units=2;tile(0,1).seen=true;tile(1,2).seen=true;const foe=tile(5,2);foe.owner='enemy';foe.capital=true;foe.units=4;foe.seen=true;tile(5,1).owner='enemy';tile(5,1).units=2;tile(5,1).seen=true;tile(4,2).seen=true;addLog('A new age begins.',`${n.name} raises its banner in the west.`);$('#startScreen').classList.add('hidden');$('#gameScreen').classList.remove('hidden');$('#factionName').textContent=n.name;$('#factionIcon').textContent=n.symbol;$('#factionFlavor').textContent=n.flavor;$('#passiveText').textContent=n.bonus;$('#rivalName').textContent=n.rival;$('#rivalIcon').textContent=n.rivalIcon;$('#campaignTitle').textContent=`${n.name}: Crown of the Continent`;render();}
function tile(x,y){return game.tiles.find(t=>t.x===x&&t.y===y)}
function getTile(id){return game.tiles.find(t=>t.id===id)}
function neighbors(t){return game.tiles.filter(o=>Math.abs(o.x-t.x)+Math.abs(o.y-t.y)===1)}
function owns(t){return t?.owner==='you'}
function isReachable(t){return neighbors(t).some(owns)}
function addLog(title,body){if(!game)return;game.log.unshift({turn:game.turn,title,body});game.log=game.log.slice(0,12);}
function notice(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function countOwner(owner){return game.tiles.filter(t=>t.owner===owner).length}
function playerUnits(){return game.tiles.filter(t=>t.owner==='you').reduce((n,t)=>n+t.units,0)}
function hasTech(id){return game.tech[id]}
function spendAP(){game.ap--;render()}
function render(){if(!game)return;renderResources();renderMap();renderRealm();renderActions();renderChronicle();renderRival();$('#turnNumber').textContent=game.turn;$('#actionPoints').textContent=`${game.ap} / 2 ACTIONS`;$('#chronicleCount').textContent=String(game.log.length).padStart(2,'0');$('#goalProgress').textContent=`${countOwner('you')} territories · rival capital at the eastern edge`;$('#mapStatus').textContent=game.ap?`${game.ap} action${game.ap===1?'':'s'} remaining this year.`:'Actions spent. End the year to continue.'}
function renderResources(){const entries=[['✧','arcana','ARC'],['▰','food','FOOD'],['◈','gold','GOLD']];$('#topResources').innerHTML=entries.map(([icon,key,label])=>`<div class="resource"><i>${icon}</i><b>${game[key]}</b><small>${label}</small></div>`).join('')}
function renderMap(){const grid=$('#mapGrid');grid.innerHTML='';game.tiles.forEach(t=>{const el=document.createElement('button');el.className=`tile terrain-${t.terrain}${t.owner?' '+(t.owner==='you'?'owned owner-you':'enemy owner-enemy'):''}${t.seen?'':' fog'}${t.capital?' tile-capital':''}${game.selected===t.id?' selected':''}`;el.setAttribute('role','gridcell');el.setAttribute('aria-label',`${t.seen?'': 'Unexplored '} ${t.owner==='you'?'Your':t.owner==='enemy'?'Rival':'Unclaimed'} ${terrainNames[t.terrain]} ${t.x+1},${t.y+1}`);const unknown=!t.seen;const label=unknown?'?':t.owner==='you'?(t.capital?'Citadel':terrainNames[t.terrain].split(' ')[0]):t.owner==='enemy'?(t.capital?'Crimson Keep':'Ashen land'):terrainNames[t.terrain].split(' ')[0];el.innerHTML=`${t.capital?'<span class="capital-mark">♛</span>':''}<span class="terrain-glyph">${unknown?'?':glyphs[t.terrain]}</span><span class="tile-label ${label.length>9?'long':''}">${label}</span>${t.owner?`<span class="tile-state">${t.owner==='you'?'✦':'☾'}</span>`:''}${t.units?`<span class="tile-unit">⚔ ${t.units}${t.veteran?` · +${t.veteran}`:''}</span>`:''}`;el.onclick=()=>selectTile(t.id);grid.appendChild(el)});const t=getTile(game.selected);const title=t.owner==='you'?(t.capital?'Your Citadel':terrainNames[t.terrain]):t.owner==='enemy'?(t.capital?'Crimson Keep':'Ashen territory'):t.seen?terrainNames[t.terrain]:'Unexplored territory';let subtitle=t.owner==='you'?`${t.units} ${nations[game.nation].unit.toLowerCase()}${t.units===1?'':'s'} stationed · ${t.veteran} veteran rank${t.veteran===1?'':'s'}`:t.owner==='enemy'?`${t.units} rival guards${t.capital?' · Enemy capital':''}`:t.seen?`${terrainNames[t.terrain]} · ${t.terrain==='water'?'Impassable':'Open for settlement'}`:'Reveal what lies beyond your borders';$('#selectedInfo').innerHTML=`<strong>${title}</strong><span>${subtitle}</span>`}
function selectTile(id){game.selected=id;getTile(id).seen=true;neighbors(getTile(id)).forEach(t=>t.seen=true);render()}
function renderRealm(){const units=game.tiles.filter(t=>t.owner==='you'&&t.units>0);$('#unitTotal').textContent=`${playerUnits()} units`;$('#unitList').innerHTML=units.length?units.map(t=>`<div class="unit-row"><span class="unit-emblem">${nations[game.nation].unitIcon}</span><div class="unit-copy"><strong>${t.capital?'Citadel Guard':terrainNames[t.terrain].split(' ')[0]+' Company'}</strong><small>${t.units} troops · rank ${t.veteran}</small></div><span class="unit-power">${power(t)} POW</span></div>`).join(''):'<div class="unit-row"><span class="unit-copy"><strong>No troops remain</strong><small>Recruit to defend your realm</small></span></div>';$('#techSummary').innerHTML=techs.map(t=>`<div class="tech-chip ${game.tech[t.id]>=t.max?'':'locked'}"><b>${t.icon} ${game.tech[t.id]}/${t.max}</b>${t.name.split(' ')[0]}</div>`).join('')}
function power(t){return t.units+t.veteran+game.tech.war+(game.nation==='sparta'?1:0)}
function renderActions(){const target=getTile(game.selected);const buttons=[];const can=game.ap>0&&!game.finished;if(!target.owner&&target.terrain!=='water'&&isReachable(target)&&target.seen){buttons.push(button('Claim · 9 ◈',claim,can&&game.gold>=9,'highlight'))}if(target.owner==='enemy'){const attackers=neighbors(target).filter(owns).sort((a,b)=>power(b)-power(a));if(attackers.length){buttons.push(button(`Attack · ${Math.max(...attackers.map(power))} power`,()=>attack(target),can,'highlight'))}}if(target.owner==='you'){buttons.push(button('Recruit · 8 ▰',()=>recruit(target),can&&game.food>=8&&game.gold>=4));if(target.units>0&&target.veteran<3)buttons.push(button(`Train · 8 ◈`,()=>train(target),can&&game.gold>=8&&game.food>=4));}if(!buttons.length){buttons.push(button(target.terrain==='water'?'Impassable':'No action available','',false))}$('#actionButtons').innerHTML=buttons.map(b=>`<button class="action-button ${b.cls}" ${b.disabled?'disabled':''}>${b.label}</button>`).join('');[...$('#actionButtons').children].forEach((el,i)=>{if(buttons[i].fn)el.onclick=buttons[i].fn});}
function button(label,fn,enabled,cls=''){return{label,fn,disabled:!enabled,cls}}
function claim(){const t=getTile(game.selected);if(game.gold<9||game.ap<1)return;game.gold-=9;t.owner='you';t.units=0;t.seen=true;neighbors(t).forEach(n=>n.seen=true);game.ap--;addLog('New lands claimed.',`${terrainNames[t.terrain]} joins ${nations[game.nation].name}.`);notice('Territory claimed.');checkWin();render()}
function recruit(t){if(game.ap<1||game.food<8||game.gold<4)return;game.food-=8;game.gold-=4;t.units+=2;game.ap--;addLog('Fresh banners rise.',`Two ${nations[game.nation].unit.toLowerCase()} join the ${t.capital?'Citadel Guard':'local garrison'}.`);notice('Two troops recruited.');render()}
function train(t){if(game.ap<1||game.gold<8||game.food<4||t.veteran>=3)return;game.gold-=8;game.food-=4;t.veteran++;game.ap--;addLog('A veteran is forged.',`${t.capital?'Citadel Guard':'Territorial company'} improves to rank ${t.veteran}.`);notice('Troops trained · +1 power.');render()}
function attack(target){if(game.ap<1)return;const attacker=neighbors(target).filter(owns).sort((a,b)=>power(b)-power(a))[0];if(!attacker)return;const offense=power(attacker)+(game.nation==='gondor'&&target.owner==='you'?1:0);const defense=target.units+target.veteran+1;game.ap--;if(offense>=defense){const survivors=Math.max(1,attacker.units-Math.max(0,defense-1));attacker.units=Math.max(1,Math.floor(attacker.units/2));target.owner='you';target.units=survivors;target.veteran=0;target.seen=true;neighbors(target).forEach(n=>n.seen=true);addLog('Victory at '+(target.capital?'Crimson Keep':terrainNames[target.terrain])+'.',`${nations[game.nation].unit} break the rival line and claim the territory.`);notice(target.capital?'The rival capital has fallen!':'Victory! The territory is yours.');}else{attacker.units=Math.max(0,attacker.units-1);if(attacker.units===0){attacker.owner=null;attacker.veteran=0}target.units=Math.max(1,target.units-1);addLog('A hard-fought defeat.',`The assault on ${terrainNames[target.terrain]} is repelled. Both sides suffer losses.`);notice('Attack repelled. Regroup and try again.')}render();checkWin()}
function openTech(){const modal=$('#modal'),card=$('#modalCard');card.innerHTML=`<div class="modal-head"><div><span class="eyebrow">A LEGACY OF KNOWLEDGE</span><h2>The research hall</h2></div><button class="modal-close" data-close="true">×</button></div><p class="help-copy">Spend an action to advance one of your disciplines. Each level stacks its bonus; the first level of a discipline is a fine start.</p><div>${techs.map(t=>{const level=game.tech[t.id],done=level>=t.max;return `<div class="tech-row"><div class="tech-icon">${t.icon}</div><div class="tech-copy"><strong>${t.name} · ${level}/${t.max}</strong><p>${t.description}</p><span class="tech-cost">${done?'MASTERED':`COST: ${t.cost} ◈ · ${Math.max(1,t.arcana-(game.nation==='hogwarts'?3:0))} ✧`}</span></div><button class="tech-action" data-tech="${t.id}" ${done||game.ap<1||game.gold<t.cost||game.arcana<Math.max(1,t.arcana-(game.nation==='hogwarts'?3:0))?'disabled':''}>${done?'Done':'Research'}</button></div>`}).join('')}</div>`;modal.classList.remove('hidden');card.querySelectorAll('[data-tech]').forEach(b=>b.onclick=()=>research(b.dataset.tech));card.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
function research(id){const t=techs.find(x=>x.id===id),costA=Math.max(1,t.arcana-(game.nation==='hogwarts'?3:0));if(!t||game.ap<1||game.tech[id]>=t.max||game.gold<t.cost||game.arcana<costA)return;game.gold-=t.cost;game.arcana-=costA;game.tech[id]++;game.ap--;addLog('A new discipline mastered.',`${t.name} advances to level ${game.tech[id]}.`);notice(`${t.name} · level ${game.tech[id]}`);closeModal();render()}
function closeModal(){ $('#modal').classList.add('hidden') }
function openHelp(){const card=$('#modalCard');card.innerHTML=`<div class="modal-head"><div><span class="eyebrow">FIELD GUIDE</span><h2>How to play</h2></div><button class="modal-close" data-close="true">×</button></div><div class="help-copy"><h3>Build your realm</h3><p>Each year gives you <b>2 actions</b>. Select a neighboring unclaimed tile and spend 9 gold to claim it. Water is impassable. Your territories earn resources every year.</p><h3>Raise your champions</h3><p>Select one of your lands to recruit two troops (8 food, 4 gold), or train its garrison (8 gold, 4 food) for +1 battle power. Troops and veterans stay at their post.</p><h3>Research & battle</h3><p>Open the research hall for three upgrade paths. Select an enemy tile and attack with the strongest adjacent garrison. Compare your troops, veteran rank, technology, and civilization bonus with the enemy defenders.</p><h3>Victory & defeat</h3><p>Capture the rival capital, or expand to 12 territories to unite the continent. If your Citadel falls, your campaign is lost. End the year to collect income and let the Ashen Court take its turn.</p></div>`;$('#modal').classList.remove('hidden');card.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
function renderChronicle(){$('#chronicle').innerHTML=game.log.map(e=>`<div class="log-entry"><time>Y${String(e.turn).padStart(2,'0')}</time><div><strong>${e.title}</strong><br>${e.body}</div></div>`).join('')}
function renderRival(){const n=countOwner('enemy'),units=game.tiles.filter(t=>t.owner==='enemy').reduce((s,t)=>s+t.units,0);$('#rivalPower').textContent=units;$('#rivalMeter').style.width=`${Math.min(100,units*5)}%`;$('#rivalStatus').textContent=n?`${n} territories held · ${units} guards remain.`:'The Ashen Court has been driven from the continent.'}
function endTurn(){if(game.finished)return;const owned=countOwner('you');game.gold+=4+owned*2+game.tech.land*3;game.food+=3+owned+game.tech.land*2;game.arcana+=1+game.tech.lore*2+(game.nation==='asgard'?2:0);enemyTurn();if(!game.finished){game.turn++;game.ap=2;game.tiles.filter(t=>t.owner).forEach(t=>neighbors(t).forEach(n=>n.seen=true));if(game.turn===5){$('#omenTitle').textContent='The red comet';$('#omenText').textContent='An omen burns above the march. The Ashen Court stirs.';addLog('A red comet crosses the sky.','Old rivalries awaken beneath its light.')}if(game.turn===10){$('#omenTitle').textContent='The long winter';$('#omenText').textContent='The age grows cold. Fortify your borders before the final march.';addLog('The long winter begins.','Every banner must choose its final cause.')}render()}}
function enemyTurn(){let cap=game.tiles.find(t=>t.owner==='you'&&t.capital);if(!cap){finish(false,'The Citadel has fallen','The Ashen Court broke through your defenses. Your people scatter into legend.');return}const enemy=game.tiles.filter(t=>t.owner==='enemy');let attacked=false;for(const foe of enemy){const target=neighbors(foe).find(t=>t.owner==='you'&&(!t.capital||foe.units>=3));if(target&&foe.units>=3&&Math.random()<.42){const ep=foe.units+1+Math.floor(Math.random()*2),dp=target.units+target.veteran+(game.nation==='gondor'?1:0)+game.tech.war;if(ep>dp){target.units=0;target.owner='enemy';target.veteran=0;target.capital=false;foe.units=Math.max(2,foe.units-1);addLog('The Ashen Court advances.',`Enemy raiders seize ${terrainNames[target.terrain]}.`);attacked=true;if(target.capital)finish(false,'The Citadel has fallen','The Ashen Court broke through your defenses. Your people scatter into legend.');break}else{foe.units=Math.max(1,foe.units-1);target.units=Math.max(1,target.units-1);addLog('The border holds.',`Your garrison repels an Ashen Court raid at ${terrainNames[target.terrain]}.`);attacked=true;break}}}if(game.finished)return;if(!attacked){const frontier=enemy.flatMap(t=>neighbors(t).filter(n=>!n.owner&&n.terrain!=='water')).filter((t,i,a)=>a.indexOf(t)===i).sort((a,b)=>a.x-b.x);if(frontier.length){const target=frontier[Math.floor(Math.random()*Math.min(frontier.length,3))];target.owner='enemy';target.units=1+Math.floor(Math.random()*2);target.seen=true;neighbors(target).forEach(n=>n.seen=true);addLog('Ashen banners advance.',`The rival claims ${terrainNames[target.terrain]} to the east.`)}else if(enemy.length){const gather=enemy.find(t=>t.capital)||enemy[0];gather.units+=1;addLog('Enemy musters.',`The Ashen Court rallies at ${gather.capital?'Crimson Keep':terrainNames[gather.terrain]}.`)}}}
function checkWin(){if(!game||game.finished)return;const enemyCapital=game.tiles.find(t=>t.capital&&t.owner==='enemy');if(!enemyCapital||countOwner('you')>=12){finish(true,'A new age dawns',!enemyCapital?'Crimson Keep has fallen. The Ashen Court bows to your banner.':'Twelve territories united under your crown. The continent is yours.')}}
function finish(win,title,copy){game.finished=true;const overlay=$('#victoryOverlay');overlay.innerHTML=`<div class="victory-card"><div class="victory-symbol">${win?'✦':'☾'}</div><p class="eyebrow">${win?'VICTORY':'THE CHRONICLES REMEMBER'}</p><h2>${title}</h2><p>${copy}</p><p><b>${nations[game.nation].name}</b> · Year ${game.turn} · ${countOwner('you')} territories</p><button class="primary" id="playAgain">Begin a new campaign &nbsp; →</button></div>`;overlay.classList.remove('hidden');$('#playAgain').onclick=()=>{overlay.classList.add('hidden');$('#gameScreen').classList.add('hidden');$('#startScreen').classList.remove('hidden');game=null;selectedNation=null;renderNationOptions()};}
let selectedNation=null;
function renderNationOptions(){const el=$('#nationOptions');el.innerHTML=Object.entries(nations).map(([id,n])=>`<button class="nation-option ${id===selectedNation?'selected':''}" data-nation="${id}"><span class="nation-head"><span class="nation-symbol">${n.symbol}</span><span class="nation-name">${n.name}</span></span><span class="nation-description">${n.desc}</span></button>`).join('');el.querySelectorAll('[data-nation]').forEach(b=>b.onclick=()=>{selectedNation=b.dataset.nation;renderNationOptions();$('#startGame').disabled=false;$('#startGame').innerHTML=`Raise the ${nations[selectedNation].name} banner <span>→</span>`})}
$('#startGame').onclick=()=>selectedNation&&startGame(selectedNation);$('#openTech').onclick=openTech;$('#helpButton').onclick=openHelp;$('#endTurn').onclick=endTurn;$('#restartGame').onclick=()=>{if(confirm('Abandon this campaign and return to civilization selection?')){game=null;$('#gameScreen').classList.add('hidden');$('#startScreen').classList.remove('hidden');selectedNation=null;renderNationOptions()}};$('#homeButton').onclick=()=>$('#restartGame').click();$('#modal').addEventListener('click',e=>{if(e.target.dataset.close)closeModal()});renderNationOptions();

